#include <algorithm>
#include <cstdio>
#include <iostream>
#include <iterator>
#include <map>
#include <numeric>
#include <string>
#include <vector>

// C++17 has no lazy streams; <algorithm> and lambdas express the same steps eagerly.
std::string show(const std::vector<int>& v) {
    std::string s = "[";
    for (size_t i = 0; i < v.size(); ++i) s += (i ? ", " : "") + std::to_string(v[i]);
    return s + "]";
}

int main() {
    std::vector<int> numbers(10);
    std::iota(numbers.begin(), numbers.end(), 1);

    // filter, then map
    std::vector<int> evenSquares;
    std::copy_if(numbers.begin(), numbers.end(), std::back_inserter(evenSquares), [](int n) { return n % 2 == 0; });
    std::transform(evenSquares.begin(), evenSquares.end(), evenSquares.begin(), [](int n) { return n * n; });
    std::cout << "Even squares: " << show(evenSquares) << "\n";

    std::vector<int> big;
    std::copy_if(numbers.begin(), numbers.end(), std::back_inserter(big), [](int n) { return n > 5; });
    double average = big.empty() ? 0.0 : std::accumulate(big.begin(), big.end(), 0.0) / big.size();
    std::printf("Average of values > 5: %.2f\n", average);

    // accumulate is C++'s reduce with an explicit identity
    int oddSum = std::accumulate(numbers.begin(), numbers.end(), 0, [](int acc, int n) { return n % 2 == 1 ? acc + n : acc; });
    std::cout << "Sum of odd numbers: " << oddSum << "\n";

    std::map<std::string, std::vector<int>> byParity;
    for (int n : numbers) byParity[n % 2 == 0 ? "even" : "odd"].push_back(n);
    std::cout << "Grouped by parity: {even=" << show(byParity["even"]) << ", odd=" << show(byParity["odd"]) << "}\n";

    std::string labels = "<";
    for (int i = 0; i < 3; ++i) labels += (i ? ", #" : "#") + std::to_string(numbers[i]);
    std::cout << "First three labels: " << labels << ">\n";

    // find_if stops at the first match, like findFirst
    auto it = std::find_if(numbers.begin(), numbers.end(), [](int n) { return n * n > 40; });
    std::cout << "First number whose square exceeds 40: " << (it != numbers.end() ? *it : -1) << "\n";
}

