import java.util.*;
import java.util.function.*;

public class LambdaBasics {
    public static void main(String[] args) {
        List<String> words = new ArrayList<>(List.of("stream", "map", "lambda", "java", "filter", "io"));

        // Before lambdas: an anonymous class implementing Comparator
        Comparator<String> byLengthOld = new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                return Integer.compare(a.length(), b.length());
            }
        };
        // The same behaviour as a lambda: parameters -> expression
        Comparator<String> byLength = (a, b) -> Integer.compare(a.length(), b.length());

        words.sort(byLengthOld);
        System.out.println("anonymous class sort: " + words);
        // thenComparing breaks ties: the three 6-letter words become alphabetical
        words.sort(byLength.thenComparing((a, b) -> a.compareTo(b)));
        System.out.println("lambda sort + ties:   " + words);

        // A lambda may capture a local variable only if it is effectively final
        int minLength = 4;
        Predicate<String> isLong = w -> w.length() >= minLength;
        // minLength = 5; // would not compile: the lambda captured minLength
        List<String> longWords = new ArrayList<>();
        words.forEach(w -> {
            if (isLong.test(w)) {
                longWords.add(w); // mutating the list object is fine; reassigning longWords is not
            }
        });
        System.out.println("words with >= " + minLength + " letters: " + longWords);

        // Block-bodied lambda with an explicit return
        BinaryOperator<Integer> clampedSum = (a, b) -> {
            int sum = a + b;
            return Math.min(sum, 100);
        };
        System.out.println("clampedSum(70, 20) = " + clampedSum.apply(70, 20));
        System.out.println("clampedSum(70, 50) = " + clampedSum.apply(70, 50));

        // A no-argument lambda: () -> value
        Supplier<String> greeting = () -> "hello from a Supplier";
        System.out.println(greeting.get());
    }
}

