#include <algorithm>
#include <functional>
#include <iostream>
#include <string>
#include <vector>

std::string show(const std::vector<std::string>& v) {
    std::string s = "[";
    for (size_t i = 0; i < v.size(); ++i) s += (i ? ", " : "") + v[i];
    return s + "]";
}

// Before lambdas: a function object (functor) class
struct ByLengthOld {
    bool operator()(const std::string& a, const std::string& b) const { return a.size() < b.size(); }
};

int main() {
    std::vector<std::string> words = {"stream", "map", "lambda", "java", "filter", "io"};

    // stable_sort keeps equal-length words in their original order, like Java's List.sort
    std::stable_sort(words.begin(), words.end(), ByLengthOld{});
    std::cout << "anonymous class sort: " << show(words) << "\n";

    // A lambda: [captures](parameters) { body }
    auto byLengthThenAlpha = [](const std::string& a, const std::string& b) {
        if (a.size() != b.size()) return a.size() < b.size();
        return a < b;
    };
    std::stable_sort(words.begin(), words.end(), byLengthThenAlpha);
    std::cout << "lambda sort + ties:   " << show(words) << "\n";

    // [minLength] captures a copy, so later changes to minLength would not affect the lambda
    const size_t minLength = 4;
    auto isLong = [minLength](const std::string& w) { return w.size() >= minLength; };
    std::vector<std::string> longWords;
    std::for_each(words.begin(), words.end(), [&](const std::string& w) {  // [&] captures by reference
        if (isLong(w)) longWords.push_back(w);
    });
    std::cout << "words with >= " << minLength << " letters: " << show(longWords) << "\n";

    std::function<int(int, int)> clampedSum = [](int a, int b) {
        int sum = a + b;
        return std::min(sum, 100);
    };
    std::cout << "clampedSum(70, 20) = " << clampedSum(70, 20) << "\n";
    std::cout << "clampedSum(70, 50) = " << clampedSum(70, 50) << "\n";

    auto greeting = [] { return std::string("hello from a Supplier"); };
    std::cout << greeting() << "\n";
}

