import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class StreamPipelineLaziness {
    public static void main(String[] args) {
        List<String> words = List.of("stream", "lambda", "map", "filter", "lazy", "java", "lambda");

        // source -> intermediate ops (filter, map, distinct, sorted, limit) -> terminal op (toList)
        List<String> result = words.stream()
                .filter(w -> w.length() > 3)
                .map(String::toUpperCase)
                .distinct()
                .sorted()
                .limit(3)
                .toList();
        System.out.println("pipeline result: " + result);
        System.out.println("distinct count: " + words.stream().distinct().count());
        System.out.println("total letters: " + words.stream().mapToInt(String::length).sum());

        // Laziness: building the pipeline prints nothing; elements flow one at a time
        // only when the terminal operation pulls them, and findFirst stops early.
        Stream<String> pipeline = words.stream()
                .filter(w -> {
                    System.out.println("  filter " + w);
                    return w.startsWith("l");
                })
                .map(w -> {
                    System.out.println("  map " + w);
                    return w.toUpperCase();
                });
        System.out.println("pipeline built, nothing processed yet");
        Optional<String> first = pipeline.findFirst();
        System.out.println("findFirst -> " + first.orElse("none"));

        // A stream can be consumed only once
        try {
            pipeline.count();
        } catch (IllegalStateException e) {
            System.out.println("reusing the stream -> IllegalStateException");
        }

        String joined = words.stream().skip(4).collect(Collectors.joining("+"));
        System.out.println("skip(4) joined: " + joined);
    }
}

