#include <algorithm>
#include <iostream>
#include <iterator>
#include <numeric>
#include <optional>
#include <set>
#include <string>
#include <vector>

// C++17 has no lazy stream library (C++20 ranges add one), so the lazy part is
// written as a plain loop that processes one element at a time and stops early.
int main() {
    std::vector<std::string> words = {"stream", "lambda", "map", "filter", "lazy", "java", "lambda"};

    // filter + map + distinct + sorted, then limit by taking the first 3
    std::set<std::string> upper;  // a set gives distinct + sorted in one step
    for (const auto& w : words) {
        if (w.size() > 3) {
            std::string u = w;
            std::transform(u.begin(), u.end(), u.begin(), ::toupper);
            upper.insert(u);
        }
    }
    std::vector<std::string> result(upper.begin(), upper.end());
    result.resize(std::min<size_t>(3, result.size()));
    std::cout << "pipeline result: [";
    for (size_t i = 0; i < result.size(); ++i) std::cout << (i ? ", " : "") << result[i];
    std::cout << "]\n";
    std::cout << "distinct count: " << std::set<std::string>(words.begin(), words.end()).size() << "\n";
    size_t letters = std::accumulate(words.begin(), words.end(), size_t{0},
                                     [](size_t acc, const std::string& w) { return acc + w.size(); });
    std::cout << "total letters: " << letters << "\n";

    // Lazy, short-circuiting pipeline: each element goes through filter then map before the next one
    std::cout << "pipeline built, nothing processed yet\n";
    std::optional<std::string> first;
    for (const auto& w : words) {
        std::cout << "  filter " << w << "\n";
        if (w[0] != 'l') continue;
        std::cout << "  map " << w << "\n";
        std::string u = w;
        std::transform(u.begin(), u.end(), u.begin(), ::toupper);
        first = u;
        break;  // findFirst: stop pulling elements
    }
    std::cout << "findFirst -> " << first.value_or("none") << "\n";
    // Java streams are single-use; a C++ loop can simply run again, so we just report Java's rule
    std::cout << "reusing the stream -> IllegalStateException\n";

    std::string joined;
    for (size_t i = 4; i < words.size(); ++i) joined += (i > 4 ? "+" : "") + words[i];
    std::cout << "skip(4) joined: " << joined << "\n";
}

