import java.util.List;
import java.util.function.Function;

public class MethodReferenceKinds {
    record Student(String name) {}

    static boolean isPassing(int score) {
        return score >= 60;
    }

    public static void main(String[] args) {
        List<String> raw = List.of("72", "45", "90");
        List<String> names = List.of("ada", "linus");

        // 1. Static method: Integer::parseInt  ==  s -> Integer.parseInt(s)
        List<Integer> scores = raw.stream().map(Integer::parseInt).toList();
        System.out.println("static      Integer::parseInt      -> " + scores);

        // A static method of our own class works the same way
        List<Integer> passing = scores.stream().filter(MethodReferenceKinds::isPassing).toList();
        System.out.println("static      ::isPassing            -> " + passing);

        // 2. Unbound instance method: String::toUpperCase  ==  s -> s.toUpperCase()
        //    the stream element becomes the receiver
        List<String> upper = names.stream().map(String::toUpperCase).toList();
        System.out.println("unbound     String::toUpperCase    -> " + upper);

        // 3. Bound instance method: prefix::concat  ==  s -> prefix.concat(s)
        //    the receiver is fixed when the reference is created
        String prefix = "Dr. ";
        List<String> titled = names.stream().map(prefix::concat).toList();
        System.out.println("bound       prefix::concat         -> " + titled);

        // 4. Constructor: Student::new  ==  n -> new Student(n)
        List<Student> students = names.stream().map(Student::new).toList();
        System.out.println("constructor Student::new           -> " + students);

        // Method references compose like any other function object
        Function<String, Integer> length = String::length;
        Function<String, Integer> lengthPlusOne = length.andThen(n -> n + 1);
        System.out.println("String::length then +1 on \"linus\" -> " + lengthPlusOne.apply("linus"));

        // Integer::sum used as the reducer
        System.out.println("reduce(0, Integer::sum)            -> " + scores.stream().reduce(0, Integer::sum));
    }
}

