#include <algorithm>
#include <functional>
#include <iostream>
#include <iterator>
#include <numeric>
#include <string>
#include <vector>

// C++ passes named functions directly (a function pointer), and std::mem_fn or a
// small lambda stands in for Java's instance-method and constructor references.
struct Student {
    std::string name;
    explicit Student(std::string n) : name(std::move(n)) {}
};

bool isPassing(int score) { return score >= 60; }
int parseInt(const std::string& s) { return std::stoi(s); }

template <typename T, typename F>
std::string show(const std::vector<T>& v, F toStr) {
    std::string s = "[";
    for (size_t i = 0; i < v.size(); ++i) s += (i ? ", " : "") + toStr(v[i]);
    return s + "]";
}

int main() {
    std::vector<std::string> raw = {"72", "45", "90"};
    std::vector<std::string> names = {"ada", "linus"};
    auto str = [](const std::string& s) { return s; };
    auto num = [](int n) { return std::to_string(n); };

    std::vector<int> scores(raw.size());
    std::transform(raw.begin(), raw.end(), scores.begin(), parseInt);  // pass the function itself
    std::cout << "static      Integer::parseInt      -> " << show(scores, num) << "\n";

    std::vector<int> passing;
    std::copy_if(scores.begin(), scores.end(), std::back_inserter(passing), isPassing);
    std::cout << "static      ::isPassing            -> " << show(passing, num) << "\n";

    std::vector<std::string> upper;
    for (std::string n : names) {
        std::transform(n.begin(), n.end(), n.begin(), ::toupper);
        upper.push_back(n);
    }
    std::cout << "unbound     String::toUpperCase    -> " << show(upper, str) << "\n";

    // Bound: the lambda captures the receiver (prefix), like prefix::concat
    std::string prefix = "Dr. ";
    std::vector<std::string> titled;
    std::transform(names.begin(), names.end(), std::back_inserter(titled),
                   [&prefix](const std::string& n) { return prefix + n; });
    std::cout << "bound       prefix::concat         -> " << show(titled, str) << "\n";

    // Constructor: emplace_back forwards the argument to Student's constructor
    std::vector<Student> students;
    for (const auto& n : names) students.emplace_back(n);
    std::cout << "constructor Student::new           -> "
              << show(students, [](const Student& s) { return "Student[name=" + s.name + "]"; }) << "\n";

    // std::mem_fn turns a member function into a callable, like String::length
    auto length = std::mem_fn(&std::string::size);
    std::cout << "String::length then +1 on \"linus\" -> " << length(std::string("linus")) + 1 << "\n";

    std::cout << "reduce(0, Integer::sum)            -> "
              << std::accumulate(scores.begin(), scores.end(), 0, std::plus<int>()) << "\n";
}

