import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.*;

public class FunctionalInterfacesDemo {
    // Our own functional interface: exactly one abstract method
    @FunctionalInterface
    interface Discount {
        double apply(double price);
    }

    public static void main(String[] args) {
        // Predicate<T>: T -> boolean, composable with and/or/negate
        Predicate<Integer> isEven = n -> n % 2 == 0;
        Predicate<Integer> isBig = n -> n > 10;
        System.out.println("isEven.and(isBig) on 12: " + isEven.and(isBig).test(12));
        System.out.println("isEven.negate() on 12:   " + isEven.negate().test(12));

        // Function<T, R>: T -> R; andThen runs left to right, compose runs right to left
        Function<Integer, Integer> plus2 = n -> n + 2;
        Function<Integer, Integer> times3 = n -> n * 3;
        System.out.println("plus2.andThen(times3) on 5: " + plus2.andThen(times3).apply(5)); // (5+2)*3
        System.out.println("plus2.compose(times3) on 5: " + plus2.compose(times3).apply(5)); // 5*3+2

        // Consumer<T>: T -> void, used for side effects
        List<String> log = new ArrayList<>();
        Consumer<String> record = log::add;
        Consumer<String> recordTwice = record.andThen(s -> log.add(s + "!"));
        recordTwice.accept("saved");
        System.out.println("Consumer log: " + log);

        // Supplier<T>: () -> T, produces values on demand
        int[] nextId = {100}; // array trick: the reference is final, its contents are not
        Supplier<Integer> ids = () -> nextId[0]++;
        System.out.println("Supplier ids: " + ids.get() + ", " + ids.get() + ", " + ids.get());

        // UnaryOperator<T> and BinaryOperator<T> are Functions whose types all match
        UnaryOperator<String> shout = s -> s.toUpperCase() + "!";
        BinaryOperator<Integer> maxOf = BinaryOperator.maxBy(Integer::compare);
        System.out.println("UnaryOperator: " + shout.apply("done") + ", BinaryOperator max: " + maxOf.apply(7, 4));

        // Any lambda with the right shape fits our custom interface
        Discount tenPercent = p -> p * 0.9;
        Discount minusFive = p -> p - 5;
        System.out.printf(Locale.ROOT, "Discount on 80.00: %.2f then %.2f%n", tenPercent.apply(80), minusFive.apply(tenPercent.apply(80)));
    }
}

