#include <vector>

// std::function<R(Args...)> plays the role of Java's functional interfaces
using IntPredicate = std::function<bool(int)>;
using IntFunction = std::function<int(int)>;

IntPredicate andP(IntPredicate a, IntPredicate b) { return [=](int n) { return a(n) && b(n); }; }
IntPredicate negate(IntPredicate p) { return [=](int n) { return !p(n); }; }
IntFunction andThen(IntFunction f, IntFunction g) { return [=](int n) { return g(f(n)); }; }
IntFunction compose(IntFunction f, IntFunction g) { return [=](int n) { return f(g(n)); }; }

int main() {
    std::cout << std::boolalpha;
    IntPredicate isEven = [](int n) { return n % 2 == 0; };
    IntPredicate isBig = [](int n) { return n > 10; };
    std::cout << "isEven.and(isBig) on 12: " << andP(isEven, isBig)(12) << "\n";
    std::cout << "isEven.negate() on 12:   " << negate(isEven)(12) << "\n";

    IntFunction plus2 = [](int n) { return n + 2; };
    IntFunction times3 = [](int n) { return n * 3; };
    std::cout << "plus2.andThen(times3) on 5: " << andThen(plus2, times3)(5) << "\n";
    std::cout << "plus2.compose(times3) on 5: " << compose(plus2, times3)(5) << "\n";

    std::vector<std::string> log;
    std::function<void(const std::string&)> record = [&log](const std::string& s) { log.push_back(s); };
    auto recordTwice = [&](const std::string& s) { record(s); log.push_back(s + "!"); };
    recordTwice("saved");
    std::cout << "Consumer log: [" << log[0] << ", " << log[1] << "]\n";

    // mutable lets the lambda change its own captured copy of nextId
    std::function<int()> ids = [nextId = 100]() mutable { return nextId++; };
    int a = ids(), b = ids(), c = ids();  // separate statements fix the evaluation order
    std::cout << "Supplier ids: " << a << ", " << b << ", " << c << "\n";

    std::function<std::string(std::string)> shout = [](std::string s) {
        for (auto& ch : s) ch = static_cast<char>(toupper(ch));
        return s + "!";
    };
    std::function<int(int, int)> maxOf = [](int x, int y) { return x >= y ? x : y; };
    std::cout << "UnaryOperator: " << shout("done") << ", BinaryOperator max: " << maxOf(7, 4) << "\n";

    std::function<double(double)> tenPercent = [](double p) { return p * 0.9; };
    std::function<double(double)> minusFive = [](double p) { return p - 5; };
    std::printf("Discount on 80.00: %.2f then %.2f\n", tenPercent(80), minusFive(tenPercent(80)));
}

