// Any function value fits; these helpers recreate Java's default composition methods.
const and = (p, q) => (x) => p(x) && q(x);
const negate = (p) => (x) => !p(x);
const andThen = (f, g) => (x) => g(f(x));
const compose = (f, g) => (x) => f(g(x));

const isEven = (n) => n % 2 === 0;
const isBig = (n) => n > 10;
console.log(`isEven.and(isBig) on 12: ${and(isEven, isBig)(12)}`);
console.log(`isEven.negate() on 12:   ${negate(isEven)(12)}`);

const plus2 = (n) => n + 2;
const times3 = (n) => n * 3;
console.log(`plus2.andThen(times3) on 5: ${andThen(plus2, times3)(5)}`);
console.log(`plus2.compose(times3) on 5: ${compose(plus2, times3)(5)}`);

const log = [];
const record = (s) => log.push(s);
const recordTwice = (s) => { record(s); log.push(`${s}!`); };
recordTwice('saved');
console.log(`Consumer log: [${log.join(', ')}]`);

// A closure over a let variable acts as a stateful Supplier
const makeIds = (start) => {
  let nextId = start;
  return () => nextId++;
};
const ids = makeIds(100);
console.log(`Supplier ids: ${ids()}, ${ids()}, ${ids()}`);

const shout = (s) => `${s.toUpperCase()}!`;
console.log(`UnaryOperator: ${shout('done')}, BinaryOperator max: ${Math.max(7, 4)}`);

const tenPercent = (p) => p * 0.9;
const minusFive = (p) => p - 5;
console.log(`Discount on 80.00: ${tenPercent(80).toFixed(2)} then ${minusFive(tenPercent(80)).toFixed(2)}`);

