import java.util.*;
import java.util.stream.*;

class Solution {
    static List<Integer> evenSquares(List<Integer> nums) {
        return nums.stream()
                .filter(n -> n % 2 == 0)   // keep the evens (works for negatives too)
                .map(n -> n * n)
                .collect(Collectors.toList());
    }
}

